questionvariables.text:
/* Synthetic data, not observations from actual Kenyan schools. */
n:60;
county_names:["Nairobi","Kiambu","Nakuru","Kisumu","Mombasa","Machakos"];
county_counts:random_permutation([6,8,9,10,12,15]);
county_raw:append(
 makelist(1,i,1,county_counts[1]),
 makelist(2,i,1,county_counts[2]),
 makelist(3,i,1,county_counts[3]),
 makelist(4,i,1,county_counts[4]),
 makelist(5,i,1,county_counts[5]),
 makelist(6,i,1,county_counts[6])
);
county_raw:random_permutation(county_raw);
/* Thirty paired low/high scores give a symmetric distribution with two moderately separated clusters. */
low_scores:makelist(49+rand(7),i,1,30);
high_scores:makelist(120-low_scores[i],i,1,30);
read_raw:append(low_scores,high_scores);
/* Different relationship variants: positive, negative, or absent. */
relcase:1+rand(3);
math_raw:makelist(
 if relcase=1 then read_raw[i]+rand(13)-6
 elseif relcase=2 then 120-read_raw[i]+rand(13)-6
 else 43+rand(35),
 i,1,n
);
/* Both school types contain both modes, with distinct median positions. */
type_raw:append(
 makelist(if i<=18 then 1 else 2,i,1,30),
 makelist(if i<=12 then 1 else 2,i,1,30)
);
setting_raw:makelist(if mod(i,2)=0 then 1 else 2,i,1,n);
class_raw:makelist(20+rand(26),i,1,n);
raw_rows:makelist(
 [i,county_raw[i],read_raw[i],math_raw[i],class_raw[i],type_raw[i],setting_raw[i]],
 i,1,n
);
rows:random_permutation(raw_rows);
ids:makelist(rows[i][1],i,1,n);
counties:makelist(rows[i][2],i,1,n);
reading:makelist(rows[i][3],i,1,n);
maths:makelist(rows[i][4],i,1,n);
classsize:makelist(rows[i][5],i,1,n);
schooltype:makelist(rows[i][6],i,1,n);
setting:makelist(rows[i][7],i,1,n);
/* Unique largest/smallest counties by construction. */
ta_largest:lmax(county_counts);
ta_smallest:lmin(county_counts);
largest_id:1;
smallest_id:1;
for k:1 thru 6 do (
 if county_counts[k]=ta_largest then largest_id:k,
 if county_counts[k]=ta_smallest then smallest_id:k
);
/* Relationship answers: 1 positive, 2 negative, 3 none, 4 curved. */
ta_rel:relcase;
ta_linear:if relcase=3 then 3 else 1;
/* Symmetric boxplot; histogram has two peaks at default bin width. */
ta_shape:1;
ta_peaks:2;
ta_hidden:2;
/* Filtering removes observations, not alters them. */
ta_filter:1;
/* Primary lower median, secondary higher; both groups overlap. */
ta_median:2;
ta_overlap:1;
/* Rescaling does not change observations or the relationship. */
ta_axis:2;
ta_axiswhy:1;
/* Dropdowns: list of [value,correct,display] triples. */
opt_rel:[[1,is(ta_rel=1),"Reading scores tend to increase as mathematics scores increase"],
 [2,is(ta_rel=2),"Reading scores tend to decrease as mathematics scores increase"],
 [3,is(ta_rel=3),"Reading scores show no clear tendency to change as mathematics scores increase"],
 [4,false,"Reading scores rise at first, then fall as mathematics scores increase"]];
opt_shape:[[1,true,"The reading scores look spread symmetrically across all schools"],
 [2,false,"Most scores are high, with a longer tail towards low scores"],
 [3,false,"Most scores are low, with a longer tail towards high scores"]];
opt_peaks:[[1,false,"Most schools have reading scores concentrated around one central value"],
 [2,true,"There seem to be two groups of schools with different typical reading scores"],
 [3,false,"Reading scores are spread fairly evenly across the whole range"]];
opt_hidden:[[1,false,"The schools' reading scores change when the bars get wider"],
 [2,true,"Wider bars can make two groups of scores look like one broad group"],
 [3,false,"Wider bars always make the two groups easier to distinguish"]];
opt_county_max:makelist([k,is(k=largest_id),county_names[k]],k,1,6);
opt_county_min:makelist([k,is(k=smallest_id),county_names[k]],k,1,6);
opt_filter:[[1,true,"Only the selected schools are shown"],
 [2,false,"The selected schools' measurements change"],
 [3,false,"The axes must represent different variables"]];
opt_median:[[1,false,"Primary"],[2,true,"Secondary"],[3,false,"The medians are equal"]];
opt_overlap:[[1,true,"Yes, their score ranges overlap"],
 [2,false,"No, the score ranges do not overlap"]];
opt_axis:[[1,false,"Yes, the underlying relationship changed"],
 [2,true,"No, only the display scale changed"]];
opt_axiswhy:[[1,true,"Axis ranges change visual impressions, not the data"],
 [2,false,"The schools have different scores in the second plot"],
 [3,false,"The correlation necessarily changes when axes are rescaled"]];
/* Compact variant identifier: observations and relationship are meaningful. */
